def test_histogram():
    # single winner
    assert histogram("a b b c") == {"b": 2}
    # tie: every word with the max count is returned
    assert histogram("a b c") == {"a": 1, "b": 1, "c": 1}
    assert histogram("a a b b") == {"a": 2, "b": 2}
    # one word
    assert histogram("dog") == {"dog": 1}
    # empty / all-space input -> empty dict
    assert histogram("") == {}
    assert histogram("   ") == {}
    # repeated spaces are ignored (empty tokens skipped)
    assert histogram("a  b") == {"a": 1, "b": 1}
```

